SOURCE tests/procedures/support/fixture.sql;
CALL bank_lab.sp_expect_ok(DATABASE(),'retry default success','CALL {db}.sp_transfer_funds_retry(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,NULL,@p3_group,@p3_debit,@p3_credit,@p3_attempts)');
SET @p3_ok=(SELECT @p3_attempts=1 AND @p3_group IS NOT NULL);
CALL bank_lab.sp_assert_true(DATABASE(),'retry default attempts',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_ok(DATABASE(),'retry explicit success','CALL {db}.sp_transfer_funds_retry(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,3,@p3_group,@p3_debit,@p3_credit,@p3_attempts)');
CALL bank_lab.sp_expect_error(DATABASE(),'retry invalid limit 0','CALL {db}.sp_transfer_funds_retry(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,0,@p3_group,@p3_debit,@p3_credit,@p3_attempts)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'retry invalid limit -1','CALL {db}.sp_transfer_funds_retry(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,-1,@p3_group,@p3_debit,@p3_credit,@p3_attempts)',5018);
CALL bank_lab.sp_expect_ok(DATABASE(),'retry large positive limit','CALL {db}.sp_transfer_funds_retry(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,101,@p3_group,@p3_debit,@p3_credit,@p3_attempts)');
SOURCE tests/procedures/support/fault_trigger.sql;
SET @p3_fault_errno=1213,@p3_fault_remaining=1;
SET @p3_log=(SELECT COALESCE(MAX(log_id),0) FROM bank_lab.Experiment_Log);
CALL bank_lab.sp_expect_ok(DATABASE(),'retry synthetic transient 1213','CALL {db}.sp_transfer_funds_retry(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,3,@p3_group,@p3_debit,@p3_credit,@p3_attempts)');
SET @p3_ok=(SELECT @p3_attempts=2 AND COUNT(*)=1 FROM bank_lab.Experiment_Log WHERE log_id>@p3_log AND db_name=DATABASE() AND exp_id='RETRY' AND event_type='DEADLOCK_RETRY');
CALL bank_lab.sp_assert_true(DATABASE(),'retry 1213 whole transaction second attempt',@p3_ok,'Expected procedure contract');
SET @p3_fault_errno=1205,@p3_fault_remaining=1;
SET @p3_log=(SELECT COALESCE(MAX(log_id),0) FROM bank_lab.Experiment_Log);
CALL bank_lab.sp_expect_ok(DATABASE(),'retry synthetic transient 1205','CALL {db}.sp_transfer_funds_retry(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,3,@p3_group,@p3_debit,@p3_credit,@p3_attempts)');
SET @p3_ok=(SELECT @p3_attempts=2 AND COUNT(*)=1 FROM bank_lab.Experiment_Log WHERE log_id>@p3_log AND db_name=DATABASE() AND event_type='LOCKWAIT_RETRY');
CALL bank_lab.sp_assert_true(DATABASE(),'retry 1205 event',@p3_ok,'Expected procedure contract');
SET @p3_fault_errno=1213,@p3_fault_remaining=1;
SET @p3_log=(SELECT COALESCE(MAX(log_id),0) FROM bank_lab.Experiment_Log);
SET @p3_failed=(SELECT COUNT(*) FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_expect_error(DATABASE(),'retry exhausted retains 1213','CALL {db}.sp_transfer_funds_retry(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,1,@p3_group,@p3_debit,@p3_credit,@p3_attempts)',1213);
SET @p3_ok=(SELECT COUNT(*)=1 AND (SELECT COUNT(*) FROM Transactions WHERE status='Failed')=@p3_failed FROM bank_lab.Experiment_Log WHERE log_id>@p3_log AND db_name=DATABASE() AND event_type='RETRY_EXHAUSTED');
CALL bank_lab.sp_assert_true(DATABASE(),'retry exhausted event no Failed',@p3_ok,'Expected procedure contract');
DROP TRIGGER p3_test_retry_fault;
